style.css:
@-moz-document domain("byjus.com") {
/* ===========================
   GTA V Night Theme for BYJU'S
   Created for UserStyles
   =========================== */

:root{
    --gta-black:#0d0d0d;
    --gta-dark:#171717;
    --gta-card:#222222;
    --gta-green:#00ff88;
    --gta-green2:#19ff9d;
    --gta-text:#ffffff;
    --gta-muted:#b8b8b8;
    --gta-shadow:0 0 20px rgba(0,255,136,.35);
}

/* Background */
html,
body{
    background:
    radial-gradient(circle at top,#1b1b1b 0%,#0b0b0b 70%);
    color:var(--gta-text)!important;
}

/* Cards */
div,
section,
article,
aside,
header,
footer,
nav{
    background:var(--gta-dark)!important;
    color:var(--gta-text)!important;
}

/* Navigation */
header,
nav{
    border-bottom:2px solid var(--gta-green)!important;
    box-shadow:var(--gta-shadow);
}

/* Buttons */
button,
input[type="submit"],
a[class*="btn"]{
    background:linear-gradient(135deg,#00ff88,#00b96b)!important;
    color:#000!important;
    border:none!important;
    border-radius:12px!important;
    font-weight:bold!important;
    transition:.3s;
}

button:hover,
input[type="submit"]:hover,
a[class*="btn"]:hover{
    transform:translateY(-2px) scale(1.03);
    box-shadow:0 0 18px rgba(0,255,136,.6);
}

/* Links */
a{
    color:var(--gta-green)!important;
}

a:hover{
    color:#6affbf!important;
}

/* Inputs */
input,
textarea,
select{
    background:#111!important;
    color:#fff!important;
    border:1px solid var(--gta-green)!important;
}

/* Cards */
[class*="card"],
[class*="Card"]{
    background:var(--gta-card)!important;
    border:1px solid rgba(0,255,136,.35)!important;
    border-radius:18px!important;
    box-shadow:var(--gta-shadow);
}

/* Images */
img{
    border-radius:12px;
}

/* Scrollbar */
::-webkit-scrollbar{
    width:10px;
}

::-webkit-scrollbar-track{
    background:#111;
}

::-webkit-scrollbar-thumb{
    background:linear-gradient(#00ff88,#00c56c);
    border-radius:20px;
}

/* Headings */
h1,h2,h3,h4,h5,h6{
    color:var(--gta-green)!important;
    text-shadow:0 0 10px rgba(0,255,136,.35);
}

/* Paragraphs */
p,
span,
li{
    color:var(--gta-muted)!important;
}

/* Tables */
table{
    background:#161616!important;
    color:white!important;
}

th{
    background:#00ff88!important;
    color:black!important;
}

td{
    border-color:#333!important;
}

/* Selection */
::selection{
    background:#00ff88;
    color:#000;
}

/* Smooth animations */
*{
    transition:
        background .25s,
        color .25s,
        border .25s,
        box-shadow .25s;
}
}
